const res = await tools.mcp__engram__mem_save({
  title:"Fixed logout cookie race",
  type:"bugfix",
  scope:"project",
  project:"marketing-api",
  topic_key:"auth/dashboard-logout",
  content:"**What**: Replaced the immediate Streamlit rerun after rendering the cookie-clearing bridge with `st.stop()`, and added a focused regression test.\n**Why**: Logout cleared Python session state but `st.rerun()` could start the next run before the browser executed the JavaScript that deleted the auth cookie; the surviving cookie then restored the login automatically.\n**Where**: dashboard.py; tests/test_dashboard_ui.py\n**Learned**: Browser-side cookie deletion must be allowed to execute before another Streamlit run begins. The existing bridge already performs navigation after clearing the cookie, so an explicit server rerun is both redundant and racy."
});
text(res);

